"<?php

namespace Tests\Feature;

use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

class InventoryTest extends TestCase
{
    use RefreshDatabase;

    protected function setUp(): void
    {
        parent::setUp();

        // Seed basic users
        $this->admin = User::create([
            'nama' => 'Admin Test',
            'email' => 'admin@test.com',
            'password' => bcrypt('password123'),
            'role' => 'administrator',
            'status' => 'aktif',
        ]);

        $this->staff = User::create([
            'nama' => 'Staff Test',
            'email' => 'staff@test.com',
            'password' => bcrypt('password123'),
            'role' => 'staff_gudang',
            'status' => 'aktif',
        ]);

        $this->pimpinan = User::create([
            'nama' => 'Pimpinan Test',
            'email' => 'pimpinan@test.com',
            'password' => bcrypt('password123'),
            'role' => 'pimpinan',
            'status' => 'aktif',
        ]);

        $this->nonaktif = User::create([
            'nama' => 'Nonaktif Test',
            'email' => 'nonaktif@test.com',
            'password' => bcrypt('password123'),
            'role' => 'staff_gudang',
            'status' => 'nonaktif',
        ]);
    }

    /**
     * Test guest can see login page.
     */
    public function test_guest_can_see_login_page(): void
    {
        $response = $this->get('/login');
        $response->assertStatus(200);
        $response->assertSee('Sistem Informasi Inventori Kantor');
    }

    /**
     * Test user login with correct credentials.
     */
    public function test_user_can_login_with_correct_credentials(): void
    {
        $response = $this->post('/login', [
            'email' => 'admin@test.com',
            'password' => 'password123',
        ]);

        $response->assertRedirect('/dashboard');
        $this->assertAuthenticatedAs($this->admin);
    }
